\label{def:quasi}
	\sloppy An \emph{$(M,A)$-quasi-isometry} between graphs $G$ and $H$ is a map $f\colon V(G)\rightarrow V(H)$ such that the following holds for fixed constants $M\geq 1, A\geq 0$, \begin{enumerate*}[label=(\alph*)]
		\item $M^{-1}d(x,y)-A  \leq d(f(x),f(y)) \leq Md(x,y)+A$ for every $x,y\in V(G)$; and \item for every $z\in V(H)$ there is $x\in V(G)$ such that $d(z,f(x))\leq A$. 
	\end{enumerate*}
	The graphs $G$ and $H$ are \emph{quasi-isometric} if there exists a quasi-isometric map $f$ between $V(G)$ and $V(H)$.

\label{lem:trace}
 	For an integer $R$, let $\mathcal{H}= (H, (V_h)_{h \in V(H)})$ be an $R$-bounded nicely rooted honest graph-partition of a graph~$G$ over a graph~$H$ which is also rooted at a node $s$. Let $r\in V_s$ be a vertex such that $V_s=B_G(r,R_s)$. 
 	\begin{enumerate}[label=(\alph*)]
 		\item\label{it:trace} For any $u\in V(G), h\in V(H), u\in V_h$ and an $(r,u)$-isometric path $P$ in $G$, $trace_{H}\left(P\right)$ is an $(s,h)$-isometric path in $H$.

 		\item\label{it:rooted-pair-preserve} Let $(x,y)$ be an $r$-rooted pair in $G$ and $g,h\in V(H)$ such that $x\in V_g, y\in V_h$. Then $(g,h)$ is an $s$-rooted pair in $H$.
 	\end{enumerate}

\label{lem:sipco-distort}
	Let $X$ and $Y$ be two graphs, $f\colon V(X)\rightarrow V(Y)$ be a function, and $r\in V(X)$ be a vertex. Let $t\geq 1, k\geq 1$ be two integers such that the following hold. \begin{enumerate}[label=(\roman*)]
		\item For any edge $ab\in E(X)$, $d_{Y}\left(f(a),f(b)\right) \leq k+1$;
		\item \sloppy For any $r$-rooted pair $(a,b)$ in $X$,  $d_{Y}\left(f(a),f(b)\right) \leq d_{X}\left(a,b\right)  + t$.
	\end{enumerate} Then, for $\{u,v\}\subseteq V(X)$, $d_{Y}\left(f(u),f(v)\right) \leq d_{X}\left(u,v\right)  + t\cdot sipco\left(X\right) + k(sipco\left(X\right)-1)$.

Assume for contradiction that there is a path $P$ in $H$ and a component $C$ of $H-V(P)$ such that $|N_H(C)\cap V(P)|\geq k+1$.
For each $u\in N_H(C)\cap V(P)$, let $r_u$ be a vertex of $C$ adjacent to $u$. 
Let $T$ be a spanning tree of $C$ and $r$ be any vertex of $C$. Set $t_1=|E(P)|$, $t_2=\max_{u\in V(C)} d_{T}\left(r,u\right) $, $t_3=t_1+t_2+2$ and $t_4=2t_3+t_1+2$. 
Define a function $\phi\colon E(H)\rightarrow \mathbb{Z}^+$ as follows.
\begin{enumerate}[label=(\roman*),topsep=0pt]
	\item For each $e\in E(T)\cup E(P)$, define $\phi(e)=1$.
	\item  For each $u\in N_H(C)\cap V(P)$, define $\phi(ur_u)=t_3-d_{T}\left(r,r_u\right) $. 
	\item For any edge $e$ that does not satisfy the above two conditions, define $\phi(e)=t_4$.  
\end{enumerate}


Construct a graph $H^*$ by replacing each edge $e$ of $H$ with a path of length $\phi(e)$. Clearly, $H^*\in \langle H \rangle$. 
We prove the following claim. 


\begin{claim}\label{clm:W}
		The path $P$ is isometric in $H^*$. 
\end{claim} 
\begin{subproof}
	By definition, $P$ is a path in $H^*$.  Let $x,y$ be the endpoints of $P$ and $Q$ be any $(x,y)$-path distinct from $P$. By definition of $H^*$, $Q$ must contain a subpath of length at least $t_1+2$ and hence $|E(Q)|>|E(P)|$.   
\end{subproof}

\begin{claim}\label{clm:ipcok+1}
	Any $r$-rooted isometric path in $H^*$ contains at most one vertex of $N_H(C)\cap V(P)$.
\end{claim}
\begin{subproof}
	By construction of $H^*$, for any $u\in N_H(C)\cap V(P)$, $d_{H^*}\left(r,u\right) = t_3$. (Indeed,  for any $u\in N_H(C)\cap V(P)$, there is an $(r,u)$-path in $H^*$ through $r_u$ that has length $t_3$ and any other $(r,u)$-path will have length at least $t_4>t_3$.) Hence, any path of $H^*$ that has $r$ as an endpoint and contains two vertices of $N_H(C)\cap V(P)$ will have length at least $t_3+1$, and thus not isometric in $H^*$.
\end{subproof}

By Claims~\ref{clm:W} and \ref{clm:ipcok+1}, $ipco\left(r,H^*\right)\geq k+1$. This implies $sipco\left(H^*\right)\geq k+1$, a contradiction.

Let $k=sipco\left(\langle H\rangle \right)$.	If $g=h$, then the lemma is trivially true. If $g=s$, then the lemma is true by Lemma~\ref{lem:equal-GF-rooted}. Therefore, we assume $s\neq g\neq h$.
	Let $P$ be a $(r,r_h)$-isometric path in $F$ that contains $r_g$.
	Let $Q=\left(g_1,g_2,\ldots,g_t\right)$ be the sequence such that for $i\in [t], g_i\in V(H)$, $s=g_1, h= g_t$, and for $i\in [t-1]$, $P$ contains a $(r_{g_i},r_{g_{i+1}})$-subpath that does not contain any vertex of $G$ apart from $r_{g_i}$ and $r_{g_{i+1}}$.
	 Clearly, $Q$ is an $(s,h)$-isometric path in $H$ that contains $g$. Therefore, $(g,h)$ is an $s$-rooted pair in $H$. Let $Q_1$ be the $(g,h)$-subpath of $Q$.
	Applying Lemma~\ref{lem:attach-ipco} on $Q_1$ and the component $C$ of $H-V(Q_1)$ that contains $s$, we have that $|N_H(C)\cap V(Q_1)|\leq k$. Let $A=N_H(C)\cap V(Q_1)$.

	\begin{claim}\label{clm:hop}
		For each node $h'\in V(Q_1)\setminus \{g\}$, there exists a node $g'\in A\setminus \{h'\}$ such that $(g',h')$ is an $s$-rooted pair in $H$ and $d_{G}\left(r_{g'},r_{h'}\right)  \leq d_{G}\left(r,r_{h'}\right)  - d_{G}\left(r,r_{g'}\right)  + 2R$. 
	\end{claim} 
	\begin{subproof}
		Fix a node $h'\in V(Q_1)\setminus \{g\}$ and let $h_1$ be the node of $Q_1$ where $d_{Q_1}\left(g,h_1\right) =d_{Q_1}\left(g,h'\right) -1$. Since $H$ is an honest partition of $G$, there exists an edge $uv\in E(G)$ such that $v\in V_{h'}$ and $u\in V_{h_1}$. Observe that $v\in \delta^{\downarrow}_{h'}$ and by  Lemma~\ref{lem:down-bd-dst},
		\begin{align}\label{eq1}
			d_{G}\left(r,v\right) =d_{G}\left(r,r_{h'}\right) 
		\end{align} 
		By Lemma~\ref{lem:dst-incerase}, $d_{G}\left(r,v\right) =d_{G}\left(r,u\right) +1$, and therefore there exists an $(r,v)$-isometric path $T$ in $G$ that contains $u$. 
		Let $Q_2=trace_{H}\left(T\right)$ and $h_2\in V(Q_2)\cap V(Q_1)$ be the node closest to $s$. Observe that $h_2\neq h'$, and $h_2\in A$. 
		Let $w$ be the vertex of $V(T)\cap V_{h_2}$ that is closest to $r$ in $G$. Observe that $w\in \delta^{\downarrow}_{h_2}$ and by  Lemma~\ref{lem:down-bd-dst},
		\begin{align}\label{eq2}
			d_{G}\left(r,w\right) =d_{G}\left(r,r_{h_2}\right) 
		\end{align} 






		\noindent By (\ref{eq1}), (\ref{eq2}) we have that, 
		\begin{align*}
			d_{G}\left(r_{h_2},r_{h'}\right)  & \leq  d_{G}\left(r_{h_2},w\right)  + d_{G}\left(w,v\right)  + d_{G}\left(v,r_{h'}\right)  & [\text{Triangle inequality}] \\
			& \leq 2R+ d_{G}\left(w,v\right)  & [\text{Definitions of }H,\mathcal{H}] \\
			& = 2R + d_{G}\left(r,v\right)  - d_{G}\left(r,w\right)  & [\text{Definition of }w \text{ and }v] \\
			& = 2R + d_{G}\left(r,r_{h'}\right)  - d_{G}\left(r,r_{h_2}\right) 
		\end{align*}
		Setting $g'=h_2$ proves the claim.
	\end{subproof}

	Let $(g'_1, g'_2, \ldots g'_{t'})$ be the maximum subsequence of $Q_1$ such that $g'_{t'}=h$, and for each $i\in [t'-1,1]$, $g'_{i}$ is the node closest to $s$ that satisfies Claim~\ref{clm:hop} when applied to $g'_{i+1}$. Observe that, $t'-1\leq k$. Observe that, $g'_1=g$. Hence, 
	\begin{align*}
		d_{G}\left(r_g,r_h\right)  & = d_{G}\left(r_{g'_1},r_{g'_{t'}}\right) 
		\leq \displaystyle\sum\limits_{i=1}^{t'-1} d_{G}\left(r_{g'_i},r_{g'_{i+1}}\right)  & [\text{Triangle inequality}] \\
		& \leq \displaystyle\sum\limits_{i=1}^{t'-1} \left(d_{G}\left(r,r_{g'_{i+1}}\right)  - d_{G}\left(r,r_{g'_i}\right) \right) + 2R(t'-1) & [\text{Claim~\ref{clm:hop}}] \\
		& = d_{G}\left(r,r_{g'_{t'}}\right)  - d_{G}\left(r,r_{g'_1}\right)  + 2R(t'-1) \\
		& = d_{F}\left(r_{g'_1},r_{g'_{t'}}\right)  + 2R(t'-1) & [\text{Construction of }F] \\
		& \le d_{F}\left(r_{g},r_h\right)  + 2Rk
	\end{align*}
	This completes the proof.

ix a node $h'\in V(Q_1)\setminus \{g\}$ and let $h_1$ be the node of $Q_1$ where $d_{Q_1}\left(g,h_1\right) =d_{Q_1}\left(g,h'\right) -1$. Since $H$ is an honest partition of $G$, there exists an edge $uv\in E(G)$ such that $v\in V_{h'}$ and $u\in V_{h_1}$. Observe that $v\in \delta^{\downarrow}_{h'}$ and by  Lemma~\ref{lem:down-bd-dst},
		\begin{align}\label{eq1}
			d_{G}\left(r,v\right) =d_{G}\left(r,r_{h'}\right) 
		\end{align} 
		By Lemma~\ref{lem:dst-incerase}, $d_{G}\left(r,v\right) =d_{G}\left(r,u\right) +1$, and therefore there exists an $(r,v)$-isometric path $T$ in $G$ that contains $u$. 
		Let $Q_2=trace_{H}\left(T\right)$ and $h_2\in V(Q_2)\cap V(Q_1)$ be the node closest to $s$. Observe that $h_2\neq h'$, and $h_2\in A$. 
		Let $w$ be the vertex of $V(T)\cap V_{h_2}$ that is closest to $r$ in $G$. Observe that $w\in \delta^{\downarrow}_{h_2}$ and by  Lemma~\ref{lem:down-bd-dst},
		\begin{align}\label{eq2}
			d_{G}\left(r,w\right) =d_{G}\left(r,r_{h_2}\right) 
		\end{align} 






		\noindent By (\ref{eq1}), (\ref{eq2}) we have that, 
		\begin{align*}
			d_{G}\left(r_{h_2},r_{h'}\right)  & \leq  d_{G}\left(r_{h_2},w\right)  + d_{G}\left(w,v\right)  + d_{G}\left(v,r_{h'}\right)  & [\text{Triangle inequality}] \\
			& \leq 2R+ d_{G}\left(w,v\right)  & [\text{Definitions of }H,\mathcal{H}] \\
			& = 2R + d_{G}\left(r,v\right)  - d_{G}\left(r,w\right)  & [\text{Definition of }w \text{ and }v] \\
			& = 2R + d_{G}\left(r,r_{h'}\right)  - d_{G}\left(r,r_{h_2}\right) 
		\end{align*}
		Setting $g'=h_2$ proves the claim.

\label{lem:F->G}
There is a function $\alpha\colon V(F)\rightarrow V(G)$ satisfying the following.
	\begin{enumerate}[label=(\alph*),topsep=0pt]
	\item  For each edge $xy\in E(F)$, $d_{G}\left(\alpha(x),\alpha(y)\right) \leq 3R+1$.
	\item For any $r$-rooted pair $(x,y)$ in $F$, $d_{G}\left(\alpha(x),\alpha(y)\right)  \leq d_{F}\left(x,y\right)  + 4R+2+2R\cdot sipco\left(\langle H\rangle\right)$. 
\end{enumerate}
